import socket,os
# find inode of 8080 listener
ino=None
for l in open('/proc/net/tcp').read().splitlines()[1:]:
    p=l.split()
    if p[3]=='0A' and int(p[1].split(':')[1],16)==8080:
        ino=p[9]
        print('8080 inode',ino)
print('--- scan all pid fds for that inode ---')
found=False
for pid in os.listdir('/proc'):
    if not pid.isdigit(): continue
    d=f'/proc/{pid}/fd'
    try: fds=os.listdir(d)
    except Exception: continue
    for fd in fds:
        try: t=os.readlink(f'{d}/{fd}')
        except Exception: continue
        if t==f'socket:[{ino}]':
            try: cmd=open(f'/proc/{pid}/cmdline').read().replace('\0',' ')
            except Exception: cmd='?'
            print('HOLDER',pid,cmd); found=True
print('found' if found else 'no holder visible in this pid namespace')
EOF
echo '--- cgroup of container vs. ss ---'; cat /proc/self/mountinfo | grep -i 'ns\|cgroup' | head -3; cat /proc/1/status | grep -i ns"}

